using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalCitySignsValidate{static FinalCitySignsValidate(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalCitySignsValidate.request")||EditorApplication.isCompiling)return;File.Delete("FinalCitySignsValidate.request");try{string dir="Assets/Scenes/Oasis/CityBuildingSigns";var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var group=scene.GetRootGameObjects().Single(g=>g.name=="City Building Signs - Shared Atlas");var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(dir+"/City Building Signs.prefab");var material=AssetDatabase.LoadAssetAtPath<Material>(dir+"/City Shared Sign Atlas.mat");var rs=group.GetComponentsInChildren<MeshRenderer>(true);var prs=prefab.GetComponentsInChildren<MeshRenderer>(true);if(rs.Length!=425||prs.Length!=425)throw new Exception("Scene/master prefab count mismatch");if(rs.Any(r=>r.sharedMaterials.Length!=1||r.sharedMaterial!=material)||prs.Any(r=>r.sharedMaterials.Length!=1||r.sharedMaterial!=material))throw new Exception("Material sharing mismatch");if(group.GetComponentsInChildren<Light>(true).Length>0||group.GetComponentsInChildren<Collider>(true).Length>0)throw new Exception("Unexpected lights/colliders");if(rs.Any(r=>!r.GetComponent<LODGroup>()||r.GetComponent<LODGroup>().GetLODs()[0].screenRelativeTransitionHeight!=.045f))throw new Exception("LOD missing");int triangles=rs.Sum(r=>(int)r.GetComponent<MeshFilter>().sharedMesh.GetIndexCount(0)/3);int images=Directory.GetFiles(dir,"*.png",SearchOption.AllDirectories).Length;int styles=Directory.GetFiles(dir+"/Templates","*.prefab").Length;if(images!=1||styles!=24)throw new Exception("Atlas/template count mismatch");var ti=(TextureImporter)AssetImporter.GetAtPath(dir+"/City Signs Atlas.png");if(ti.GetPlatformTextureSettings("Android").format!=TextureImporterFormat.ASTC_4x4||!ti.mipmapEnabled)throw new Exception("Mobile texture settings");int errors=ShaderUtil.GetShaderMessages(material.s